def integrate_master():
    knowledge_path = "datasets/destinations/destinations_rich_knowledge.json"
    with open(knowledge_path, "r", encoding="utf-8") as f:
        existing = json.load(f)

    # Filter out replaced cities
    replaced = set(MASTER_DESTINATIONS.keys())
    kept = [d for d in existing if d.get("city") not in replaced and d.get("country") not in replaced]

    new_items = []
    for dest, pois in MASTER_DESTINATIONS.items():
        for p in pois:
            p["city"] = dest
            p["region"] = "Asia"
            p["country"] = "India" if dest == "Tamil Nadu" else "Nepal"
            new_items.append(p)

    final_knowledge = new_items + kept
    with open(knowledge_path, "w", encoding="utf-8") as f:
        json.dump(final_knowledge, f, indent=2)

    print(f"Master integration complete! Total POIs in database: {len(final_knowledge)}")

if __name__ == "__main__":
    integrate_master()
